import React from "react";
import "./AboutMeHero.css";
import HeroProfileAvatar from "../../components/heroProfileAvatar/HeroProfileAvatar";
import HeroSocialPanel from "../../components/heroSocialPanel/HeroSocialPanel";
import { greeting } from "../../portfolio";
import { Fade } from "react-reveal";

export default function AboutMeHero({ theme }) {
  const portraitSrc = `${process.env.PUBLIC_URL || ""}/${greeting.portraitPath}`;

  return (
    <Fade bottom duration={1600} distance="32px">
      <section className="about-me-hero" id="about-me">
        <div className="about-me-hero__grid">
          <div className="about-me-hero__text">
            <p
              className="about-me-hero__eyebrow"
              style={{ color: theme.imageHighlight }}
            >
              {greeting.heroEyebrow}
            </p>
            <h1 className="about-me-hero__title" style={{ color: theme.text }}>
              About me
            </h1>
            <p
              className="about-me-hero__role"
              style={{ color: theme.secondaryText }}
            >
              {greeting.roleTitle}
            </p>
            <p
              className="about-me-hero__body"
              style={{ color: theme.secondaryText }}
            >
              {greeting.aboutMe}
            </p>
            <p
              className="about-me-hero__body about-me-hero__body--muted"
              style={{ color: theme.secondaryText }}
            >
              {greeting.subTitle}
            </p>
          </div>
          <aside
            className="about-me-hero__aside"
            aria-label="Profile photo and social links"
          >
            <HeroProfileAvatar
              theme={theme}
              src={portraitSrc}
              alt={greeting.title}
              initials={greeting.logo_name}
              size="compact"
            />
            <HeroSocialPanel
              theme={theme}
              actionButtons={[
                { text: "Download resume", href: greeting.resumeLink },
                {
                  text: "\u2B50 Star on GitHub",
                  href: greeting.portfolio_repository,
                },
              ]}
            />
          </aside>
        </div>
      </section>
    </Fade>
  );
}
