import React from "react";
import "./HeroProfileAvatar.css";

export default function HeroProfileAvatar({
  theme,
  src,
  alt,
  initials,
  size = "hero",
  priority = false,
}) {
  const accent = theme.imageHighlight || "#0E6BA8";
  const badge = String(initials || "UR")
    .replace(/\s/g, "")
    .slice(0, 4)
    .toUpperCase();

  return (
    <figure
      className={`hero-profile-avatar hero-profile-avatar--${size}`}
      style={{ "--avatar-accent": accent }}
    >
      <div className="hero-profile-avatar__ring">
        <img
          className="hero-profile-avatar__img"
          src={src}
          alt={alt}
          width={size === "hero" ? 320 : 240}
          height={size === "hero" ? 320 : 240}
          loading={priority ? "eager" : "lazy"}
          decoding="async"
        />
        <span className="hero-profile-avatar__badge" aria-hidden="true">
          {badge}
        </span>
      </div>
    </figure>
  );
}
