import React from "react";
import "./Greeting.css";
import HeroProfileAvatar from "../../components/heroProfileAvatar/HeroProfileAvatar";
import HeroSocialPanel from "../../components/heroSocialPanel/HeroSocialPanel";
import { greeting } from "../../portfolio";
import { Fade } from "react-reveal";

export default function Greeting(props) {
  const theme = props.theme;
  const portraitSrc = `${process.env.PUBLIC_URL || ""}/${greeting.portraitPath}`;

  return (
    <Fade bottom duration={2000} distance="40px">
      <div className="greet-main" id="greeting">
        <div className="greeting-main">
          <div className="greeting-text-div">
            <div className="greeting-copy">
              {greeting.heroEyebrow && (
                <p
                  className="greeting-eyebrow"
                  style={{ color: theme.imageHighlight }}
                >
                  {greeting.heroEyebrow}
                </p>
              )}
              <h1 className="greeting-text" style={{ color: theme.text }}>
                {greeting.title}
              </h1>
              {greeting.roleTitle && (
                <p
                  className="greeting-role-title"
                  style={{ color: theme.text }}
                >
                  <span className="greeting-role-accent" style={{ color: theme.imageHighlight }}>
                    {greeting.roleTitle}
                  </span>
                </p>
              )}
              {greeting.nickname && (
                <h2 className="greeting-nickname" style={{ color: theme.text }}>
                  ( {greeting.nickname} )
                </h2>
              )}
              <p
                className="greeting-text-p subTitle"
                style={{ color: theme.secondaryText }}
              >
                {greeting.subTitle}
              </p>
            </div>
          </div>
          <aside className="greeting-aside" aria-label="Profile and links">
            <HeroProfileAvatar
              theme={theme}
              src={portraitSrc}
              alt={greeting.title}
              initials={greeting.logo_name}
              size="hero"
              priority
            />
            <HeroSocialPanel
              theme={theme}
              actionButtons={[
                { text: "Download resume", href: greeting.resumeLink },
                {
                  text: "\u2B50 Star on GitHub",
                  href: greeting.portfolio_repository,
                },
              ]}
            />
          </aside>
        </div>
      </div>
    </Fade>
  );
}
