import React from "react";
import "./LoaderLogo.css";
import { greeting } from "../../portfolio";

const ORBIT_ICONS = [
  { icon: "logos:kotlin", label: "Kotlin", angle: 0 },
  { icon: "simple-icons:jetpackcompose", label: "Jetpack Compose", angle: 90 },
  { icon: "logos:android-icon", label: "Android", angle: 180 },
  { icon: "mdi:api", label: "APIs", angle: 270 },
];

/**
 * Splash branding with orbiting Kotlin / Compose / Android icons.
 */
export default function LoaderLogo({ theme, id }) {
  const textColor = "#ffffff";
  const accent = theme.imageHighlight || "#0E6BA8";
  const glow = theme.highlight || "#A6E1FA";

  return (
    <div
      className="splash-brand"
      id={id}
      style={{
        color: textColor,
        "--splash-accent": accent,
        "--splash-glow": glow,
      }}
    >
      <div className="splash-brand__ambience" aria-hidden="true" />

      <div className="splash-brand__orbit splash-brand__orbit--spin" aria-hidden="true">
        {ORBIT_ICONS.map((item) => (
          <div
            key={item.label}
            className="splash-brand__orbit-item"
            style={{ transform: `rotate(${item.angle}deg) translateY(calc(-1 * var(--orbit-r)))` }}
          >
            <div className="splash-brand__orbit-inner">
              <span
                className="splash-brand__orbit-icon iconify"
                data-icon={item.icon}
                data-inline="false"
                title={item.label}
              />
            </div>
          </div>
        ))}
      </div>

      <div
        className="splash-brand__ring splash-brand__ring--outer"
        style={{
          borderColor: `${textColor}40`,
          boxShadow: `0 0 0 1px ${textColor}18, 0 0 56px ${accent}4d`,
        }}
      />
      <div
        className="splash-brand__ring splash-brand__ring--inner"
        style={{
          borderColor: `${accent}aa`,
        }}
      />

      <div className="splash-brand__text">
        <h1 className="splash-brand__name">{greeting.title}</h1>
        {greeting.roleTitle && (
          <p className="splash-brand__role">{greeting.roleTitle}</p>
        )}
        <p className="splash-brand__stack" aria-hidden="true">
          Kotlin · Jetpack Compose · Android
        </p>
      </div>
    </div>
  );
}
