import React from "react";
import "./HeroSocialPanel.css";
import { socialMediaLinks } from "../../portfolio";
import Button from "../button/Button";

export default function HeroSocialPanel({
  theme,
  actionButtons = [],
  className = "",
}) {
  return (
    <div className={`hero-social-panel ${className}`.trim()}>
      <p className="hero-social-panel__label" style={{ color: theme.secondaryText }}>
        Connect
      </p>
      <div className="hero-social-panel__icons" role="list">
        {socialMediaLinks.map((media, i) => {
          const isMail = media.link.startsWith("mailto:");
          return (
            <a
              key={i}
              role="listitem"
              href={media.link}
              className="hero-social-panel__icon"
              style={{ backgroundColor: media.backgroundColor }}
              target={isMail ? undefined : "_blank"}
              rel={isMail ? undefined : "noopener noreferrer"}
              aria-label={media.name}
              title={media.name}
            >
              <i className={`fab ${media.fontAwesomeIcon}`} aria-hidden="true" />
            </a>
          );
        })}
      </div>
      {actionButtons.length > 0 && (
        <div className="hero-social-panel__actions">
          {actionButtons.map((btn, i) => (
            <Button
              key={i}
              text={btn.text}
              newTab={btn.newTab !== false}
              href={btn.href}
              theme={theme}
              className="hero-social-panel__btn-wrap"
            />
          ))}
        </div>
      )}
    </div>
  );
}
